/* Read power keys independently of the gamepad. No exclusive input grab. */
#include <time.h>
#include <errno.h>
static int powerFds[32],powerCount,powerHeld,powerPending;
static uint64_t powerGuard;
static uint64_t monotonicMs84(void){struct timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return (uint64_t)ts.tv_sec*1000+ts.tv_nsec/1000000;}
static int writeText84(const char*path,const char*value){int fd=open(path,O_WRONLY|O_CLOEXEC);if(fd<0)return 0;size_t n=strlen(value);int ok=write(fd,value,n)==(ssize_t)n;close(fd);return ok;}
static int readText84(const char*path,char*out,size_t size){int fd=open(path,O_RDONLY|O_CLOEXEC);if(fd<0)return 0;ssize_t n=read(fd,out,size-1);close(fd);if(n<0)return 0;out[n]=0;return 1;}
static void powerEdge84(int code,int value){if(code!=KEY_POWER&&code!=KEY_SLEEP)return;if(monotonicMs84()<powerGuard)return;if(value==1)powerHeld=1;else if(value==0&&powerHeld){powerHeld=0;powerPending=1;}}
static void openPower84(void){for(int i=0;i<32;i++){char path[96],name[256]={0};snprintf(path,sizeof(path),"/dev/input/event%d",i);int fd=open(path,O_RDONLY|O_NONBLOCK|O_CLOEXEC);if(fd<0)continue;unsigned long bits[(KEY_MAX+sizeof(unsigned long)*8)/(sizeof(unsigned long)*8)]={0};int word=sizeof(unsigned long)*8;if(ioctl(fd,EVIOCGBIT(EV_KEY,sizeof(bits)),bits)>=0&&((bits[KEY_POWER/word]>>(KEY_POWER%word))&1||(bits[KEY_SLEEP/word]>>(KEY_SLEEP%word))&1)){ioctl(fd,EVIOCGNAME(sizeof(name)),name);powerFds[powerCount++]=fd;fprintf(stderr,"BaetaCalc: POWER %s (%s)\n",path,name);const char*paths[]={"/sys/class/input/event%d/device/power/wakeup","/sys/class/input/event%d/device/device/power/wakeup","/sys/class/input/event%d/device/../power/wakeup"};for(int k=0;k<3;k++){char state[40];snprintf(path,sizeof(path),paths[k],i);if(readText84(path,state,sizeof(state))&&strstr(state,"disabled")){if(writeText84(path,"enabled"))fprintf(stderr,"BaetaCalc: wakeup POWER ativado %s\n",path);}}}else close(fd);}fprintf(stderr,"BaetaCalc: POWER devices=%d\n",powerCount);}
static void pollPower84(void){for(int i=0;i<powerCount;i++){struct input_event ev;for(int n=0;n<64&&read(powerFds[i],&ev,sizeof(ev))==sizeof(ev);n++)if(ev.type==EV_KEY){if(ev.code==KEY_POWER||ev.code==KEY_SLEEP)fprintf(stderr,"BaetaCalc: POWER code=%u value=%d\n",ev.code,ev.value);powerEdge84(ev.code,ev.value);}}}
static int suspend84(void){powerPending=0;char available[128];if(!readText84("/sys/power/state",available,sizeof(available))){showMessage("Standby indisponível: consulte o log de arranque","Standby unavailable: check startup log",0);return 0;}const char*state=strstr(available,"mem")?"mem":strstr(available,"standby")?"standby":strstr(available,"freeze")?"freeze":NULL;if(!state){showMessage("O firmware não disponibiliza suspensão","Firmware does not expose suspend",0);return 0;}save();for(int i=0;i<2;i++)if(r[i]){rr=r[i];color((SDL_Color){0,0,0,255});pSDL_RenderClear(rr);pSDL_RenderPresent(rr);}fprintf(stderr,"BaetaCalc: suspend %s\n",state);int ok=writeText84("/sys/power/state",state);int error=errno;powerHeld=0;powerGuard=monotonicMs84()+1500;for(int i=0;i<powerCount;i++){struct input_event ev;while(read(powerFds[i],&ev,sizeof(ev))==sizeof(ev)){} }if(ok){fprintf(stderr,"BaetaCalc: retomada da suspensão\n");clearMessage();}else{fprintf(stderr,"BaetaCalc: falha suspend: %s\n",strerror(error));showMessage("Não foi possível suspender; consulte o log","Could not suspend; check startup log",0);}for(int i=0;i<2;i++)if(w[i])pSDL_RaiseWindow(w[i]);return ok;}
